-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;
SET input_format_orc_dictionary_as_low_cardinality = 1;

-- Reading ORC unions with string-like branches must not depend on the stripes' physical encodings:
-- the branch hints pair CHAR with the FixedString alternative of the same length and STRING with
-- the String alternative, whether or not the alternatives are LowCardinality-wrapped (schema
-- inference wraps them when it sees a dictionary-encoded stripe). Without the pairing both branches
-- stay ambiguous, are read per the current stripe's encoding, and a supported schema fails
-- depending on the file's encoding choices.

-- union<char(1),string>, both branches dictionary-encoded. Rows: 'a', 'hello', 'b', 'world'.
SELECT '-- char/string union, dictionary-encoded';
DESC format(ORC, unhex(''));
SELECT u, variantType(u) FROM format(ORC, unhex('')) ORDER BY toString(u);
-- The plain-typed explicit schema over the dictionary-encoded file needs the branch hints: without
-- them the branches materialize as LowCardinality and cannot be cast back to this Variant.
SELECT u, variantType(u) FROM format(ORC, 'u Variant(FixedString(1), String)', unhex('')) ORDER BY toString(u) SETTINGS allow_suspicious_variant_types = 1;
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u) SETTINGS input_format_orc_dictionary_as_low_cardinality = 0;

-- The same logical schema and data, direct-encoded.
SELECT '-- char/string union, direct-encoded';
DESC format(ORC, unhex(''));
SELECT u, variantType(u) FROM format(ORC, 'u Variant(FixedString(1), String)', unhex('')) ORDER BY toString(u) SETTINGS allow_suspicious_variant_types = 1;
-- The LowCardinality-typed explicit schema over the direct-encoded file, the mirror case.
SELECT u, variantType(u) FROM format(ORC, 'u Variant(LowCardinality(FixedString(1)), LowCardinality(String))', unhex('')) ORDER BY toString(u) SETTINGS allow_suspicious_variant_types = 1;

-- union<char(1),string> spanning two stripes, with a null payload in each branch.
-- Rows: 'a', 's', 'a', 's', 'a', 's' | 'b', 'hello', 'c', 'world', NULL, NULL.
SELECT '-- char/string union spanning two stripes';
SELECT u, variantType(u) FROM format(ORC, unhex('')) ORDER BY toString(u);

-- union<string,string> with the first branch dictionary-encoded and the second direct. The branches
-- are logically identical, so the duplicate-branch rejection must fire regardless of the encodings.
SELECT '-- duplicate string branches with different physical encodings';
DESC format(ORC, unhex('')); -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }
SELECT u FROM format(ORC, 'u Variant(String, LowCardinality(String))', unhex('')) FORMAT Null SETTINGS allow_suspicious_variant_types = 1; -- { serverError UNKNOWN_TYPE }
